       TO_CHAR(last_refresh_date, 'YYYY-MM-DD HH24:MI') AS last_refresh
  FROM user_mviews
 WHERE mview_name = 'CUSTOMER_SALES_MV';

BEGIN
  DBMS_MVIEW.REFRESH(list => 'CUSTOMER_SALES_MV', method => 'C');
END;
/

