DROP MATERIALIZED VIEW customer_sales_mv;

CREATE MATERIALIZED VIEW LOG ON orders
  WITH ROWID, SEQUENCE (customer_id, amount)
  INCLUDING NEW VALUES;

SELECT master, log_table FROM user_mview_logs;

